'use strict';
let trackSettings={basis:'disclosed',period:'365',min:3,gain:'',win:'',office:'',sort:'avg'};
function trackRecord(person,settings=trackSettings,records=data,prices=PRICES,now=Date.now()){
 const groups=new Map(),cutoff=settings.period==='all'?-Infinity:now-Number(settings.period)*86400000;
 for(const r of records){if(r.person!==person||r.type!=='Purchase'||!['Stock','ADR','ETF'].includes(r.asset)||r.quality==='User-provided'||Date.parse(r.traded)<cutoff||Date.parse(r.traded)>now)continue;const key=r.ticker+'|'+r.traded,old=groups.get(key);if(!old||(disclosedDate(r)||'9999')<(disclosedDate(old)||'9999'))groups.set(key,r)}
 const returns=[],dates=[];let stale=0;
 for(const r of groups.values()){const p=prices[r.ticker],d=settings.basis==='trade'?r.traded:disclosedDate(r),base=p?.closes?.[d];if(!d||!p||p.error||!(base>0)||!(p.latest>0)||p.asOf<d)continue;returns.push((p.latest/base-1)*100);dates.push(p.asOf);if(p.stale)stale++}
 return {count:returns.length,total:groups.size,avg:returns.length?returns.reduce((a,b)=>a+b,0)/returns.length:null,win:returns.length?100*returns.filter(n=>n>0).length/returns.length:null,first:dates.sort()[0],last:dates.at(-1),stale};
}
function rankPeople(people,settings=trackSettings){return people.map(person=>({person,m:trackRecord(person,settings)})).filter(({person,m})=>(!settings.office||data.some(r=>r.person===person&&r.chamber===settings.office))&&m.count>=settings.min&&(settings.gain===''||m.avg!==null&&m.avg>=Number(settings.gain))&&(settings.win===''||m.win!==null&&m.win>=Number(settings.win))).sort((a,b)=>settings.sort==='name'?a.person.localeCompare(b.person):((settings.sort==='count'?b.m.count:settings.sort==='win'?b.m.win:b.m.avg)??-Infinity)-((settings.sort==='count'?a.m.count:settings.sort==='win'?a.m.win:a.m.avg)??-Infinity)||a.person.localeCompare(b.person)).map(x=>x.person)}
function trackCard(person){const m=trackRecord(person),fmt=n=>n===null?'—':(n>=0?'+':'')+n.toFixed(1)+'%';return `<div class="track-metrics"><span><small>Avg. ${trackSettings.basis==='trade'?'since purchase':'since disclosure'}</small><b class="${m.avg===null?'muted':m.avg>=0?'gain':'loss'}">${fmt(m.avg)}</b></span><span><small>Win rate</small><b>${m.win===null?'—':m.win.toFixed(0)+'%'}</b></span><span><small>Priced / eligible buys</small><b>${m.count} / ${m.total}</b></span></div><p class="muted">Closes ${m.first?date(m.first)+(m.last!==m.first?'–'+date(m.last):''):'unavailable'}${m.stale?' · '+m.stale+' stale':''}</p>`}
function initTrackFilters(){const ids={Basis:'basis',Period:'period',Min:'min',Gain:'gain',Win:'win',Office:'office',Sort:'sort'};for(const [suffix,key]of Object.entries(ids)){$('#track'+suffix).value=String(trackSettings[key]);$('#track'+suffix).addEventListener(['Gain','Win'].includes(suffix)?'input':'change',()=>{trackSettings[key]=$('#track'+suffix).value;renderPeople()})}$('#trackReset').onclick=()=>{trackSettings={basis:'disclosed',period:'365',min:3,gain:'',win:'',office:'',sort:'avg'};for(const [suffix,key]of Object.entries(ids))$('#track'+suffix).value=String(trackSettings[key]);renderPeople()}}
